insert into public.destinations (slug, name, description, short_description, location, category, image_url, latitude, longitude, rating, opening_hours, entrance_fee, best_time_to_visit, how_to_get_there, travel_tips)
values
  ('moalboal', 'Moalboal', 'Moalboal is famous for its turquoise waters, sardine runs, and laid-back beach vibe. It offers a mix of snorkeling adventures, cliffside dining, and scenic sunset spots along the coast.', 'Sardine run paradise and laid-back coastal escapes.', 'Cebu South Coast', 'Beaches', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80', 9.9447, 123.3962, 4.8, 'Open daily, 6:00 AM – 8:00 PM', 'Free access; snorkeling tours from ₱1,000', 'November to May', 'About 2.5 to 3 hours by bus or private van from Cebu City.', ARRAY['Bring reef-safe sunscreen', 'Book snorkeling early', 'Carry cash for local food stalls']::text[]),
  ('kawasan-falls', 'Kawasan Falls', 'Kawasan Falls is one of Cebu’s most scenic waterfalls. The cool emerald pool is perfect for a refreshing dip, while the canyon trek and cliff jumping add thrill for adventure seekers.', 'Turquoise falls and canyon adventure in Cebu’s south.', 'Badian, Cebu', 'Waterfalls', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80', 9.8771, 123.2729, 4.7, 'Open daily, 6:00 AM – 5:00 PM', '₱40 for local visitors; guide fees extra', 'December to April', 'A 1- to 2-hour drive from Cebu City via Barili or Badian road.', ARRAY['Wear water shoes', 'Bring a waterproof bag', 'Expect muddy trails']::text[]),
  ('bantayan-island', 'Bantayan Island', 'Bantayan Island captures the charm of a rural island getaway with powdery sand beaches, cozy beach huts, and a peaceful vibe. It is ideal for island hopping and romantic getaways.', 'Stunning island beaches and tranquil island life.', 'Northern Cebu', 'Islands', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80', 11.1698, 123.7535, 4.9, 'Open daily, 24/7', 'No entry fee; ferry + resort costs vary', 'March to June', 'Take a ferry from Hagnaya Port in Cebu northward to Santa Fe.', ARRAY['Reserve ferry tickets ahead', 'Bring cash for island transport', 'Check weather before crossing']::text[]),
  ('malapascua-island', 'Malapascua Island', 'Known for its excellent diving, Malapascua Island is a favorite for ocean lovers and beach lovers alike. It combines warm waters, vibrant reefs, and a relaxed lifestyle.', 'Diving haven with powdery beaches and clear blue waters.', 'Northern Cebu', 'Islands', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1200&q=80', 11.3251, 123.9554, 4.8, 'Open daily, 24/7', 'No entry fee; dive packages vary', 'March to June', 'Ferry from Maya Port or Cebu City coastal terminals to Malapascua.', ARRAY['Bring dive certification details', 'Avoid stormy afternoons', 'Book island transfers early']::text[]),
  ('oslob', 'Oslob', 'Oslob is a favorite for those seeking the rare chance to see whale sharks up close. The town also offers beaches, waterfalls, and a strong local culture for visitors to enjoy.', 'Whale shark encounters and coastal adventure.', 'Southern Cebu', 'Adventure', 'https://images.pexels.com/photos/1001682/pexels-photo-1001682.jpeg?auto=compress&cs=tinysrgb&w=1200', 9.531, 123.38, 4.6, 'Open daily, 5:30 AM – 12:00 PM', '₱1,000 to ₱2,000 depending on package', 'November to May', 'Approximately 3 to 4 hours by bus from Cebu City.', ARRAY['Follow local guidelines', 'Book with accredited operators', 'Bring a waterproof camera']::text[]),
  ('magellans-cross', 'Magellan''s Cross', 'A symbol of Cebu’s early Christian history, Magellan’s Cross marks the site where Christianity was first introduced to the Philippines.', 'Historic landmark of the country’s first Christian roots.', 'Cebu City', 'Historical Sites', 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=1200&q=80', 10.2932, 123.9055, 4.7, 'Open daily, 8:00 AM – 5:00 PM', 'Free', 'Any time of year', 'A short ride from downtown Cebu City and major hotels.', ARRAY['Visit early for cooler weather', 'Avoid midday crowds', 'Dress modestly if entering church areas']::text[]),
  ('basilica-minore-del-santo-nino', 'Basilica Minore del Santo Niño', 'The Basilica is one of the most important religious landmarks in the country and a pillar of Cebu’s spiritual heritage. Its centuries-old architecture and devotional atmosphere make it a must-visit.', 'Historic basilica and beloved Cebu landmark.', 'Cebu City', 'Historical Sites', 'https://images.unsplash.com/photo-1540541338287-41700207dee6?auto=format&fit=crop&w=1200&q=80', 10.2918, 123.9052, 4.8, 'Open daily, 8:00 AM – 6:00 PM', 'Free', 'Any time', 'Located near Plaza Sugbo in downtown Cebu City.', ARRAY['Visit during mass for a deeper cultural experience', 'Dress respectfully']::text[]),
  ('temple-of-leah', 'Temple of Leah', 'Inspired by the Taj Mahal, the Temple of Leah is a grand Roman-inspired structure perched on a hill with panoramic views over Cebu. It is both a memorial and an excellent lookout point.', 'Roman-inspired tribute with panoramic hilltop views.', 'Busay, Cebu', 'Historical Sites', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 10.3564, 123.8825, 4.7, 'Open daily, 8:00 AM – 6:00 PM', '₱150 per person', 'Morning or late afternoon', 'A 30-minute drive from Cebu City via the upland roads of Busay.', ARRAY['Bring light layers for cooler air', 'Go before sunset for best lighting']::text[]),
  ('sirao-garden', 'Sirao Garden', 'Nicknamed the “Little Amsterdam of Cebu,” Sirao Garden is a patchwork of flowers and greenery layered on rolling hills. It is a favorite for photos, relaxations, and cool mountain air.', 'Flower garden with stunning hilltop views.', 'Busay, Cebu', 'Nature', 'https://images.unsplash.com/photo-1466692476868-aef1dfb1e735?auto=format&fit=crop&w=1200&q=80', 10.3457, 123.8979, 4.8, 'Open daily, 6:00 AM – 6:00 PM', '₱50 to ₱100', 'Morning to late afternoon', 'A scenic, uphill drive from Cebu City through Busay.', ARRAY['Bring a hat and water', 'Visit after rain for vibrant blooms']::text[]),
  ('tops-cebu', 'Tops Cebu', 'Tops Cebu offers iconic panoramic views of the city and coastline. It is a relaxing stop for sunset dinners, scenic photos, and quick café time.', 'Sky-high overlooks and city sunsets.', 'Busay, Cebu', 'Mountains', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 10.3576, 123.8969, 4.7, 'Open daily, 10:00 AM – 10:00 PM', 'No entrance fee; food and drinks extra', 'Late afternoon to evening', 'Drive up via the Busay road, roughly 30 minutes from the city center.', ARRAY['Arrive before sunset for best views', 'Bring a light jacket']::text[]),
  ('fort-san-pedro', 'Fort San Pedro', 'Fort San Pedro is Cebu’s oldest triangular fort and a reflection of colonial history. It offers a compact but engaging walk through Cebu’s military past.', 'Historic fort and a glimpse into colonial Cebu.', 'Cebu City', 'Historical Sites', 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=1200&q=80', 10.293, 123.9059, 4.5, 'Open daily, 9:00 AM – 6:00 PM', '₱30', 'Any time', 'A few minutes from downtown Cebu City.', ARRAY['Great quick stop before city tours', 'Pair it with nearby church visits']::text[]),
  ('mactan-shrine', 'Mactan Shrine', 'The Mactan Shrine commemorates the legacy of Lapu-Lapu and the heroic resistance against Spanish colonialism. It is a meaningful site for history lovers and travelers exploring the island.', 'Cultural landmark honoring Lapu-Lapu.', 'Lapu-Lapu City', 'Historical Sites', 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=1200&q=80', 10.3275, 124.0239, 4.5, 'Open daily, 8:00 AM – 6:00 PM', 'Free', 'Any time', 'A short drive from Mactan resorts and airport facilities.', ARRAY['Good stop while touring Mactan', 'Pair with a beach walk']::text[]),
  ('simala-shrine', 'Simala Shrine', 'Known for its fairy-tale architecture, Simala Shrine is a pilgrimage destination and a favorite religious stop for travelers and devotees alike.', 'Fairy-tale church perched in the hills of Cebu.', 'Sibonga, Cebu', 'Culture', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 9.9849, 123.5858, 4.8, 'Open daily, 6:00 AM – 7:00 PM', 'Free', 'Any time', 'About 1.5 hours from Cebu City by road.', ARRAY['Dress appropriately', 'Go early for quiet prayer time']::text[]),
  ('camotes-islands', 'Camotes Islands', 'Camotes Islands are perfect for travelers looking for a more local, less crowded island experience. The islands feature calm beaches, island hopping routes, and abundant natural landscapes.', 'Hidden island escapes with raw natural charm.', 'Middle Cebu', 'Islands', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80', 10.606, 124.333, 4.6, 'Open daily, 24/7', 'Ferry and local transport vary', 'March to June', 'Take a ferry from Cebu City or Danao to the Camotes group.', ARRAY['Arrange a boat tour early', 'Stock up on essentials before arrival']::text[]),
  ('osmena-peak', 'Osmeña Peak', 'Osmeña Peak offers one of the best mountain views in Cebu. The jagged ridge and cool breeze provide a rewarding hike for adventure lovers and photographers.', 'Highland ridge walk with dramatic scenery.', 'Dalaguete, Cebu', 'Mountains', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 9.397, 123.389, 4.7, 'Open daily, 6:00 AM – 5:00 PM', '₱20 to ₱50', 'December to May', 'Drive about 2 hours from Cebu City through the mountain roads of Dalaguete.', ARRAY['Bring sturdy shoes', 'Start early to avoid heat']::text[]),
  ('sumilon-island', 'Sumilon Island', 'Sumilon Island stands out with its white sand bar, clear waters, and luxurious island feel. It is a peaceful escape where guests can lounge, snorkel, or enjoy a beach picnic.', 'White sand bar and calm waters near Oslob.', 'Oslob, Cebu', 'Islands', 'https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1200&q=80', 9.494, 123.355, 4.7, 'Open daily, 8:00 AM – 5:00 PM', '₱500 to ₱1,500 depending on package', 'November to April', 'A short boat ride from Oslob or a resort transfer arranged by local operators.', ARRAY['Bring a dry bag', 'Choose a seaside stay for sunset']::text[]),
  ('cebu-safari', 'Cebu Safari', 'Cebu Safari offers a distinctive wildlife experience with a large animal park and scenic safari roads. It is a great stop for families and nature enthusiasts.', 'Wildlife adventure and family-friendly outdoor fun.', 'Liloan, Cebu', 'Family', 'https://images.unsplash.com/photo-1546182990-dffeafbe841d?auto=format&fit=crop&w=1200&q=80', 10.426, 123.892, 4.6, 'Open daily, 9:00 AM – 5:00 PM', '₱800 and up', 'Morning', 'Around 1 hour from Cebu City via the north road toward Liloan.', ARRAY['Bring sun protection', 'Arrive early for cooler weather']::text[]),
  ('anjo-world', 'Anjo World', 'Anjo World is a family-friendly amusement park with rides, scenic gardens, and a lively atmosphere perfect for groups and kids. It is a fun stop for evening outings.', 'Amusement park energy for family fun days.', 'Minglanilla, Cebu', 'Family', 'https://images.unsplash.com/photo-1517849845537-4d257902454a?auto=format&fit=crop&w=1200&q=80', 10.275, 123.767, 4.3, 'Open daily, 9:00 AM – 9:00 PM', '₱500 and up', 'Afternoon to evening', 'About 45 minutes from central Cebu by road.', ARRAY['Bring ID for group tickets', 'Avoid weekends if you prefer shorter lines']::text[]),
  ('carbon-market', 'Carbon Market', 'A classic Cebu landmark, Carbon Market is bustling with local produce, street food, and everyday city life. It is an excellent place to shop and sample Cebuano culture.', 'Local market experience with lively city energy.', 'Cebu City', 'Shopping', 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80', 10.298, 123.9, 4.4, 'Open daily, 5:00 AM – 9:00 PM', 'Free', 'Morning for shopping, evening for food', 'Near downtown Cebu City, easy to reach by taxi or jeepney.', ARRAY['Bring cash', 'Bargain respectfully', 'Go early for freshest goods']::text[]),
  ('colon-street', 'Colon Street', 'Colon Street is one of the oldest streets in the Philippines and a core commercial district in Cebu. It is lively, historic, and full of local shopping opportunities.', 'Historic commercial strip alive with Cebu energy.', 'Cebu City', 'Shopping', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', 10.295, 123.898, 4.2, 'Open daily, 24/7', 'Free', 'Afternoon to evening', 'Located in central Cebu City, close to downtown attractions.', ARRAY['Keep valuables secure', 'Explore side streets for hidden gems']::text[])
insert into public.restaurants (slug, name, description, cuisine, location, image_url, price_range, rating, latitude, longitude)
values
  ('cebu-lechon', 'Cebu Lechon House', 'A local favorite known for crisp crunchy skin and juicy, flavorful lechon served with classic Cebuano sides.', 'Cebu Lechon', 'Cebu City', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1200&q=80', '₱₱', 4.9, null, null),
  ('seafood-spot', 'Seafood Spot', 'Fresh seafood platters and grilled specialties served with ocean views and a laid-back island atmosphere.', 'Seafood', 'Mactan', 'https://images.unsplash.com/photo-1559847844-5315695dadae?auto=format&fit=crop&w=1200&q=80', '₱₱₱', 4.8, null, null),
  ('la-paz-batchoy', 'La Paz Batchoy', 'Comforting noodle soup with rich flavors, savory broth, and a classic Cebuano crowd-pleasing taste.', 'Filipino', 'Cebu City', 'https://images.unsplash.com/photo-1559847844-5315695dadae?auto=format&fit=crop&w=1200&q=80', '₱₱', 4.7, null, null),
  ('street-food-stop', 'Street Food Stop', 'Cebu’s vibrant street snacks and grilled classics offer an authentic market food crawl in the heart of the city.', 'Street Food', 'Carbon Market', 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=1200&q=80', '₱', 4.6, null, null),
  ('sunrise-cafe', 'Sunrise Café', 'A pleasant coffee and brunch stop with mountain views, relaxed seating, and freshly brewed Cebu coffee.', 'Cafés', 'Busay', 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1200&q=80', '₱₱', 4.8, null, null),
  ('harbor-fine-dining', 'Harbor Fine Dining', 'Specialty seafood and elevated Cebu-inspired dishes in a polished waterfront setting for celebratory meals.', 'Fine Dining', 'Mactan', 'https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1200&q=80', '₱₱₱₱', 4.9, null, null),
  ('sugar-bowl', 'Sugar Bowl', 'Cheesecakes, coffee, and sweet treats make it a favorite place to slow down with dessert and conversation.', 'Desserts', 'Cebu City', 'https://images.unsplash.com/photo-1551024601-bec78aea704b?auto=format&fit=crop&w=1200&q=80', '₱₱', 4.7, null, null),
  ('barrio-south', 'Barrio South Grill', 'A warm neighborhood spot for grilled meats, rice meals, and tropical drinks with a casual local feel.', 'Filipino', 'Lahug', 'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=1200&q=80', '₱₱', 4.8, null, null)
