-- Generated from src/data/cebuData.ts (20 destinations). Re-running updates existing slugs.
on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description,
  short_description = excluded.short_description,
  location = excluded.location,
  category = excluded.category,
  image_url = excluded.image_url,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  rating = excluded.rating,
  opening_hours = excluded.opening_hours,
  entrance_fee = excluded.entrance_fee,
  best_time_to_visit = excluded.best_time_to_visit,
  how_to_get_there = excluded.how_to_get_there,
  travel_tips = excluded.travel_tips;

-- Existing restaurant records are seeded so restaurant favorites can use foreign keys too.
on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description,
  cuisine = excluded.cuisine,
  location = excluded.location,
  image_url = excluded.image_url,
  price_range = excluded.price_range,
  rating = excluded.rating,
  latitude = excluded.latitude,
  longitude = excluded.longitude;
